export const AVATARS=[['red-gen3','Rouge'],['leaf-gen3','Vert'],['brendan-gen3','Explorateur'],['may-gen3','Exploratrice'],['lucas','Aurore boréale'],['dawn','Étoile du matin'],['ethan','Voyageur'],['lyra','Voyageuse'],['hilbert','Horizon'],['hilda','Aventure'],['nate','Champion'],['rosa','Championne'],['acetrainer','Top Dresseur'],['acetrainerf','Top Dresseuse']];
export function normalizePlayer(raw){return{name:String(raw?.name||'Dresseur').trim().slice(0,20)||'Dresseur',avatar:AVATARS.some(([id])=>id===raw?.avatar)?raw.avatar:'red-gen3'}}
export const trainerSrc=id=>'assets/trainers/'+(AVATARS.some(([key])=>key===id)?id:'red-gen3')+'.png';
export function profilePage(g){const p=normalizePlayer(g.profileDraft||g.state.player);return g.heading('TON IDENTITÉ DANS POKÉWORLD','Profil de dresseur','Ton nom et ton sprite apparaissent chez tes adversaires et tes alliés.')+`<section class="player-profile panel"><div class="player-preview"><img id="player-preview" src="${trainerSrc(p.avatar)}" alt="Ton sprite de dresseur"><span class="eyebrow">CARTE DE DRESSEUR</span><h2>${g.escape(p.name)}</h2><span>${g.state.roster.length} Pokémon · Tour étage ${g.state.floor}</span></div><div><label class="name-field">Nom de dresseur<input id="player-name" maxlength="20" value="${g.escape(p.name)}" autocomplete="off"></label><h3>Choisis ton sprite</h3><div class="avatar-picker">${AVATARS.map(([id,label])=>`<button class="${id===p.avatar?'selected':''}" data-act="profile-avatar" data-avatar="${id}" title="${label}" aria-label="${label}" aria-pressed="${id===p.avatar}"><img src="${trainerSrc(id)}" alt=""></button>`).join('')}</div><button class="primary" data-act="profile-save">Enregistrer mon profil</button><p class="muted">Le profil et ta progression sont conservés dans ce navigateur.</p></div></section>`}
